def es_ancestro(x, y, hechos):
    # caso base: ¿x es progenitor directo de y?
    if (x, y) in hechos['progenitor']:
        return True
    # caso recursivo: buscar intermediario
    for z in hechos['progenitor'].get(x, []):
        if es_ancestro(z, y, hechos):
            return True
    return False
